from typing import Dict

def histogram(test: str) -> Dict[str, int]:
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    >>> histogram('a b c')
    { 'a': 1, 'b': 1, 'c': 1 }
    >>> histogram('a b b a')
    { 'a': 2, 'b': 2 }
    >>> histogram('a b c a b')
    { 'a': 2, 'b': 2 }
    >>> histogram('b b b b a')
    { 'b': 4 }
    >>> histogram('')
    {  }
    """
    # Split the string into individual characters based on whitespace
    chars = test.split()

    # If the input string is empty or contains only whitespace, return an empty dict
    if not chars:
        return {}

    # Count occurrences of each character
    counts = {}
    for char in chars:
        counts[char] = counts.get(char, 0) + 1

    # Find the maximum frequency
    max_count = max(counts.values())

    # Return only those characters that have the maximum frequency
    return {char: count for char, count in counts.items() if count == max_count}

